   772	        var paginationNext = pagination ? pagination.querySelector('[data-page-action=\"next\"]') : null;
   773	        var pageSize = 8;
   774	        var currentPage = 1;
   775	        var totalPages = 1;
   776	
   777	        function compareCards(a, b, sortValue) {
   778	          var aFeatured = Number(a.dataset.featured || 0);
   779	          var bFeatured = Number(b.dataset.featured || 0);
   780	          var aUpdated = Date.parse(a.dataset.updatedDate || '') || 0;
   781	          var bUpdated = Date.parse(b.dataset.updatedDate || '') || 0;
   782	          var aName = normalizeText((a.querySelector('h3') || {}).textContent || '');
   783	          var bName = normalizeText((b.querySelector('h3') || {}).textContent || '');
   784	
   785	          if (sortValue === 'name-asc') {
   786	            return aName.localeCompare(bName, 'vi');
   787	          }
   788	
   789	          if (sortValue === 'featured-first') {
   790	            return bFeatured - aFeatured || bUpdated - aUpdated || aName.localeCompare(bName, 'vi');
   791	          }
   792	
   793	          return bUpdated - aUpdated || bFeatured - aFeatured || aName.localeCompare(bName, 'vi');
   794	        }
   795	
   796	        function renderPagination(totalItems) {
   797	          if (!pagination || !paginationPages || !paginationPrev || !paginationNext) return;
   798	          totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
   799	          if (currentPage > totalPages) currentPage = totalPages;
   800	
   801	          if (totalItems <= pageSize) {
   802	            pagination.hidden = true;
   803	            paginationPages.innerHTML = '';
   804	            return;
   805	          }
   806	
   807	          pagination.hidden = false;
   808	          var buttons = [];
   809	          for (var page = 1; page <= totalPages; page += 1) {
   810	            buttons.push('<button type=\"button\" class=\"jobs-pagination-page' + (page === currentPage ? ' is-active' : '') + '\" data-page-number=\"' + page + '\">' + page + '</button>');
   811	          }
   812	          paginationPages.innerHTML = buttons.join('');
   813	          paginationPrev.disabled = currentPage <= 1;
   814	          paginationNext.disabled = currentPage >= totalPages;
   815	        }
   816	
   817	        function applyFilters(options) {
   818	          options = options || {};
   819	          var query = normalizeText(searchInput ? searchInput.value : '');
   820	          var location = normalizeText(locationSelect ? locationSelect.value : '');
   821	          var experience = normalizeText(experienceSelect ? experienceSelect.value : '');
   822	          var sortValue = sortSelect ? sortSelect.value : 'updated-desc';
   823	
   824	          var matched = cards.filter(function (card) {
   825	            var searchBlob = normalizeText(card.dataset.search || card.textContent || '');
   826	            var locationValue = normalizeText(card.dataset.location || '');
   827	            var experienceValue = normalizeText(card.dataset.experience || '');
   828	            var matchesQuery = !query || searchBlob.indexOf(query) !== -1;
   829	            var matchesLocation = !location || locationValue === location;
   830	            var matchesExperience = !experience || experienceValue === experience;
   831	            return matchesQuery && matchesLocation && matchesExperience;
   832	          });
   833	
   834	          matched.sort(function (a, b) { return compareCards(a, b, sortValue); });
   835	
   836	          if (!options.keepPage) currentPage = 1;
   837	          renderPagination(matched.length);
   838	
   839	          var pageStart = (currentPage - 1) * pageSize;
   840	          var pageEnd = pageStart + pageSize;
   841	          var visibleSlice = matched.slice(pageStart, pageEnd);
   842	          var visibleSet = new Set(visibleSlice);
   843	
   844	          cards.forEach(function (card) {
